"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[8910],{3036:e=>{e.exports=JSON.parse('{"functions":[{"name":"new","desc":"Creates a signal.","params":[{"name":"onError","desc":"Called with the error text when a handler throws. Defaults to `warn`.","lua_type":"((string) -> ())?"}],"returns":[{"desc":"","lua_type":"Signal<T>\\n"}],"function_type":"static","source":{"line":44,"path":"src/Signal.luau"}},{"name":"connect","desc":"Registers a handler and returns a connection to remove it with.","params":[{"name":"self","desc":"","lua_type":"Signal<T>"},{"name":"handler","desc":"","lua_type":"(T) -> ()"}],"returns":[{"desc":"","lua_type":"Connection\\n"}],"function_type":"static","errors":[{"lua_type":"\\"Signal:connect expects a function\\"","desc":"The handler was not callable."}],"source":{"line":57,"path":"src/Signal.luau"}},{"name":"fire","desc":"Calls every connected handler with `value`.","params":[{"name":"self","desc":"","lua_type":"Signal<T>"},{"name":"value","desc":"","lua_type":"T"}],"returns":[],"function_type":"static","source":{"line":85,"path":"src/Signal.luau"}},{"name":"disconnectAll","desc":"Removes every handler.","params":[{"name":"self","desc":"","lua_type":"Signal<T>"}],"returns":[],"function_type":"static","source":{"line":109,"path":"src/Signal.luau"}}],"properties":[],"types":[],"name":"Signal","desc":"A minimal event, used for [Matchmaker]\'s `matched`, `aborted`, `queued` and\\n`cancelled`. Muster ships its own so the package has no runtime dependencies.\\n\\nHandlers fire synchronously, in connection order, on the thread that raised\\nthe event. A handler that throws is reported and skipped; the remaining\\nhandlers still run. Disconnecting from inside a handler is safe, because each\\nfire iterates a snapshot of the handler list.\\n\\n```lua\\nlocal connection = queue.matched:connect(function(match)\\n\\tprint(match.matchId)\\nend)\\n\\nconnection:disconnect()\\n```","source":{"line":22,"path":"src/Signal.luau"}}')}}]);